import{_ as t,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Docubetter Meeting 2020-10-14","description":"","frontmatter":{"title":"Ceph Docubetter Meeting 2020-10-14","date":"2020-10-14T00:00:00.000Z","updated":"2020-10-15T00:00:00.000Z","tags":["Ceph","文档更新","分布式存储","开发指南","GitHub"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Docubetter_Meeting_2020-10-14.md","filePath":"posts/2020/Ceph_Docubetter_Meeting_2020-10-14.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Docubetter_Meeting_2020-10-14.md"};function a(s,e,n,u,c,p){return l(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 某日，时间略晚于预定开始时间<br><strong>参会人员：</strong> 会议主持人及其他相关人员</p><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容： <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容：&quot;">​</a></h4><ol><li><p><strong>Pull Request 374-51 (FADM)</strong></p><ul><li>讨论了FADM（Faster and More Scalable Document）的Pull Request，这是一个未来文档变更的重要来源。目前无需立即行动，但需保持关注。</li></ul></li><li><p><strong>GitHub行为变更</strong></p><ul><li>决定不再要求在doc目录内的提交必须有“Signed-off-by”标签，以避免通过GitHub Web界面进行的更改被阻止。</li></ul></li><li><p><strong>CFDF细节PR更新</strong></p><ul><li>主持人正在处理一个CFDF相关的Pull Request，预计将在接下来几小时内或最迟明天完成。</li></ul></li><li><p><strong>文档系统（FFS）的改进</strong></p><ul><li>针对Josh Cullen提出的关于侧边栏顶级链接无法正常工作的bug，主持人已通过将链接集合到restructuredText文档中的toctree来解决。同时，移除了之前注释掉的HTML代码，并添加了<code>:hidden:</code>选项以避免toctree在文档中显示。</li><li>主持人请求Patrick检查这些更改是否影响了他们的需求。</li></ul></li><li><p><strong>RADOS文档更新</strong></p><ul><li>Anthony Diatri对RADOS文档进行了大量更新，主持人与其进行了深入的合作，更新已成功整合到文档中。</li></ul></li><li><p><strong>defio与docs.ceph.com同步问题</strong></p><ul><li>讨论了defio与docs.ceph.com不同步的问题，提出了可能通过自动化工具来解决这一问题。</li></ul></li><li><p><strong>旧Pull Request的处理</strong></p><ul><li>讨论了如何处理因“Signed-off-by”检查而阻塞的旧Pull Request，建议重新运行测试或创建新的Pull Request来清理积压。</li></ul></li><li><p><strong>文档更新与维护</strong></p><ul><li>主持人计划对开发指南进行全面检查和更新，并确保在即将发布的Pacific版本中，文档集是全面、准确且易于导航的。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>不再要求doc目录内的提交必须有“Signed-off-by”标签。</li><li>将处理旧Pull Request的积压问题，通过重新运行测试或创建新PR来解决。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完成CFDF细节PR。</li><li>继续更新和维护文档，特别是FFS和开发指南。</li><li>探索自动化工具以解决defio与docs.ceph.com的同步问题。</li><li>确保Pacific版本发布时，文档集是全面、准确且易于导航的。</li></ul><p><strong>会议结束时间：</strong> 20分钟后<br><strong>下一次会议：</strong> 待定</p><p><strong>备注：</strong> 会议中提到的具体技术细节和代码更改需要进一步的技术审查和验证。</p>',10)])])}const h=t(r,[["render",a]]);export{g as __pageData,h as default};
